#include <iostream>
#include <unordered_map>
#include <utility>

int cal(int n, int m) {
    if (n < m) {
        std::swap(n, m);
    }
    if (m == 1) {
        static std::unordered_map<int, int> dt = {
            {0, 0},
            {1, 1},
            {2, 2},
            {3, 3},
            {4, 2},
            {5, 1}
        };
        return dt[n % 6];
    }
    if (n == 7) {
        if (m == 2) {
            return 2;
        }
        return (n * m) % 2;
    } else if (n >= 4) {
        return (n * m) % 2;
    } else {
        static std::unordered_map<std::pair<int, int>, int, 
            std::hash<int>, 
            std::equal_to<std::pair<int, int>>> dt2 = {
            {{3, 2}, 2},
            {{3, 1}, 3},
            {{2, 2}, 4},
            {{2, 1}, 2}
        };
        auto it = dt2.find({n, m});
        if (it != dt2.end()) {
            return it->second;
        } else {
            return (n * m) % 2;
        }
    }
}

int main() {
    int n, m;
    std::cin >> n >> m;
    std::cout << n * m - cal(n, m) << std::endl;
    return 0;
}
